var n=`1340-picarones`;var a=`world-1340`;var t=`PE`;var s=`south-america`;var o=8;var r=129;var u={en:`Picarones`,ua:`Пікаронес`};var l={en:`Picarones is a dish from Peru featuring sweet potato, pumpkin, all-purpose flour, instant yeast. This home-sized recipe records each ingredient at the step where it is used. Dark brown sugar syrup substitutes for traditional chancaca/panela syrup.`,ua:`Пікаронес, страва кухні країни Перу з такими основними складниками: батат, гарбуз, пшеничне борошно універсальне, інстантні дріжджі. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Сироп із темного коричневого цукру замінює традиційну чанкаку/панелу.`};var d=[{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`sweet-potato`,450,`g`],[`pumpkin`,400,`g`],[`water`,800,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 12 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 12 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:12,i:[[`all-purpose-flour`,310,`g`],[`instant-yeast`,9,`g`],[`anise-seeds`,6,`g`]]},{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 60 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 60 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:60,i:[]},{en:`With wet hands shape dough into rings with a hole; fry in batches until golden, then coat in warm brown-sugar-anise syrup.`,ua:`Вологими руками сформуйте з тіста кільця з отвором; смажте до золотистості й полийте теплим сиропом із коричневого цукру й анісу.`,t:[`deep-frying`],m:17,i:[[`canola-oil`,850,`ml`]]},{en:`Cook the listed sauce ingredients over medium-low heat for about 12 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 12 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:12,i:[[`dark-brown-sugar`,260,`g`],[`water`,250,`ml`],[`cassia-cinnamon`,8,`g`]]}];var g={slug:n,id:a,country:`PE`,region:s,servings:8,minutes:129,title:u,text:l,steps:d};export{t as country,g as default,a as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,u as title};